//! Copies the syntax table generated by Nix into `OUT_DIR`.
//!
//! The table lives in `assets/syntax.nix` and is generated by
//! `nix/scripts/gen-syntax.py`. This build script does NOT generate it — it
//! only locates the finished file. Generating here would reimplement Nix logic
//! (invariant 5) and would leave the source of truth.
//!
//! The same shape as `ronoctua-brain`'s and `ronoctua-tokens`' build scripts,
//! down to the reason the destination is deleted first.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_SYNTAX_RS");

    let generated = env::var("RONOCTUA_SYNTAX_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_SYNTAX_RS is not set.\n\
             \n\
             The syntax table is generated by Nix out of assets/syntax.nix.\n\
             Enter the environment with `direnv allow` (or `nix develop`), which sets\n\
             the variable, or build through the flake with `nix build`.\n\
             \n\
             Generating the table here would reimplement Nix logic (invariant 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("syntax.rs");
    // DELETE FIRST. The file comes from the store, and `fs::copy` inherits the
    // read-only mode along with the content: on the second generation the
    // destination already exists without write permission and the copy fails
    // with "Permission denied", inside a build.rs.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
